    return True


def remove_duplicate(lst: List[int]) -> List[int]:
    """Return a copy of input list without duplicate elements.

    Example:
    >>> remove_duplicate([0, 1, 2, 2, 3])
    [0, 1, 2, 3]
    """
    new_l = []
    for i in range(0, len(lst)):
        if lst[i] not in new_l:
            new_l.append(lst[i])
    return new_l

