def _get_max_paren_groups(paren_string: str, start_idx: int) -> int:
    if start_idx >= len(paren_string):
        return 0
    open_count = _get_open_counter(paren_string[start_idx])
    max_depth = open_count
    # find the max depth for the next iteration
    for i in range(start_idx + open_count, len(paren_string)):
        depth = _get_open_counter(paren_string, i) + 1
        max_depth = max(depth, max_depth)
    return max_depth


def _get_open_counter(paren_string: str, start_idx: int) -> int:
    count = 0
    while start_idx < len(paren_string):
        if paren_string[start_idx] == '(':
            count += 1
            start_idx += 1
        elif paren_string[start_idx] == ')':
            count -= 1
            start_idx += 1
    return count

