def is_valid_path(path):
    """ Given a path, returns true if it's valid, false otherwise """

    if not isinstance(path, str):
        return False

    stack = ['ROOT']
    i = 0
    while i < len(path):
        char = path[i]
        if i == len(path) - 1:
            stack.append(char)
            i += 1
        elif char == '\\':
            if stack[-1] == '\\':
                stack.pop()
            else:
                stack.append(char)
                i += 1
        elif char == '/':
            if len(stack) < 2:
                stack.append(char)
            else:
                top = stack.pop()
                if top == '\\':
                    stack.pop()
                elif top == '/':
                    stack.pop()
                else:
                    return False
            if stack[-1] == '\\':
                stack.pop()
        else:
            stack.append(char)
        i += 1

    return stack[-1] == '\\'


