def factorial(n: int) -> int:
    """ It returns factorial of n.

    n > 12 is not guaranteed, as it can throw OverflowError.

    >>> factorial(5)
    120
    """
    if n < 0:
        return 0
    return 1 if n == 0 else n * factorial(n - 1)

def fibonacci(n: int) -> int:
    """ It returns fibonacci sequence of n.

    >>> fibonacci(5)
    5
    """
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1 or n == 2:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

