def combine_groups_to_paren_string(group_list: List[str]) -> str:
    """ Group list is a list of strings. Your goal is to combine them all into a paren string.
    Note that group_list might be empty.
    >>> combine_groups_to_paren_string([])
    '('
    >>> combine_groups_to_paren_string(['()'])
    '(())'
    >>> combine_groups_to_paren_string(['()', '(()()', '((()))(())'])
    '((()))()'
    """
    combined_paren = ''
    for group in group_list:
        if len(group) > 1:
            combined_paren += f"({group[1: -1]})"
        else:
            combined_paren += group
    return combined_paren


