def has_close_words(words: List[str], threshold: float) -> bool:
    """ Check if in given list of words, are any two words have the same number of
    matching characters in them
    >>> has_close_words(["easy", "hero", "realistic"], 0.25)
    True
    >>> has_close_words(["this", "thick", "thanksgiving"], 0.25)
    False
    """
    if words is None or len(words) < 2:
        return False
    words = [w.lower() for w in words]
    sorted_words = sorted(words, key=lambda s: s.lower())
    for i in range(1, len(sorted_words)):
        if (len(sorted_words[i]) - len(sorted_words[i - 1])) / len(
            sorted_words[i - 1]
        ) > threshold:
            return False
    return True


