def is_balanced(paren_string: str) -> bool:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    return whether in this string, the parentheses are balanced or not.
    A string with balanced parentheses means that each open parenthesis has a proper closing parenthesis and that no
    parenthesis was opened without a proper closing parenthesis later.
    >>> is_balanced('( )')
    True
    >>> is_balanced('((()))')
    True
    >>> is_balanced('((())')
    False
    """
    groups = separate_paren_groups(paren_string)
    return all(group == '' for group in groups)


