def depth_for_parens(paren_string: str) -> int:
    """ Input to this function is a string of parentheses and nothing else.
    Return the deepest level of nesting.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> depth_for_parens('(()())')
    2
    """
    depth = max_depth = depth_in_parens = 0
    for c in paren_string:
        depth_in_parens += 1
        if c == "(":
            if depth == max_depth:
                depth_in_parens -= 1
            else:
                max_depth = depth_in_parens
                depth = depth_in_parens
        elif c == ")":
            if depth == max_depth:
                depth -= 1
            else:
                max_depth = depth
    return max_depth


